    },
    {
      "campo": "resolucao.antes.formulas",
      "depois": [
        "curiosity = curiosidade; inquisitiveness = curiosidade, vontade de investigar",
        "downgraded = rebaixado (de grave para leve); mild = leve",
        "Curiosity killed the cat = ser curioso demais pode trazer perigo"
      ],
      "motivo": "Linguagem mais simples e sem a palavra 'inquisitividade'."
    },
    {
      "campo": "resolucao.passos[1].conta",
